package dev.horizonlab.parity;
import com.google.gson.*;import com.mojang.serialization.Codec;import java.io.*;import java.lang.reflect.*;import java.nio.file.*;import java.util.*;
import net.minecraft.core.component.*;import net.minecraft.world.item.*;import net.minecraft.world.SimpleContainer;
/** Actual SimpleContainer methods over aliased ItemStack objects and bound prototypes. */
public final class VanillaSimpleContainerOracle {
 static final class Stop extends RuntimeException {}
 static Item[] items;static DataComponentType<Integer>[] keys;static Field components,count,patchMap;static Object removed;
 static Field field(Class<?> c,String n)throws Exception{var f=c.getDeclaredField(n);f.setAccessible(true);return f;}
 static int integer(JsonObject o,String k){return o.get(k).getAsInt();}
 static int key(Object k){for(int i=0;i<keys.length;i++)if(keys[i]==k)return i;throw new AssertionError();}
 static int item(Item i){for(int k=0;k<items.length;k++)if(items[k]==i)return k;throw new AssertionError();}
 static String opt(Object v){return v==null||v==removed?"none":v.toString();}
 static DataComponentMap prototype(JsonArray a){var b=DataComponentMap.builder();for(var e:a){var p=e.getAsJsonArray();b.set(keys[p.get(0).getAsInt()],p.get(1).getAsInt());}return b.build();}
 static DataComponentPatch patch(JsonArray a){var b=DataComponentPatch.builder();for(var e:a){var p=e.getAsJsonArray();int k=p.get(0).getAsInt();if(p.get(1).isJsonNull())b.remove(keys[k]);else b.set(keys[k],p.get(1).getAsInt());}return b.build();}
 static final class Data {
  PrintWriter out;ItemStack[] refs;C c;JsonObject op;int calls;IdentityHashMap<ItemStack,Integer> identities=new IdentityHashMap<>();
  int id(ItemStack s){return identities.computeIfAbsent(s,k->identities.size());}
  String snapshot(ItemStack s){try{var raw=(PatchedDataComponentMap)components.get(s);var p=new StringJoiner(",");for(var e:((Map<?,?>)patchMap.get(raw.asPatch())).entrySet())p.add(key(e.getKey())+"="+opt(e.getValue()));var v=new StringJoiner(",");for(var k:keys)v.add(opt(s.get(k)));return id(s)+" "+item(s.getItem())+" "+count.getInt(s)+" "+s.getCount()+" "+s.getPopTime()+" "+s.isEmpty()+" "+s.getMaxStackSize()+" | "+v+" | "+p;}catch(Exception e){throw new AssertionError(e);}}
  void all(){for(int i=0;i<refs.length;i++)out.println("ref "+i+" "+snapshot(refs[i]));for(int i=0;i<c.getContainerSize();i++)out.println("slot "+i+" "+snapshot(c.getItems().get(i)));out.println("empty "+snapshot(ItemStack.EMPTY));out.println("container "+c.getContainerSize()+" "+c.isEmpty()+" "+c.countItem(items[0])+" "+c.countItem(items[1])+" "+c.countItem(items[2]));}
  void event(String name){calls++;out.println("event "+name+" "+calls);all();if(calls==integer(op,"fail_at"))throw new Stop();if(calls==integer(op,"mutate_at")){refs[integer(op,"mutate_ref")].setCount(integer(op,"after_count"));refs[integer(op,"mutate_ref")].set(DataComponents.MAX_STACK_SIZE,integer(op,"after_max"));int slot=integer(op,"mutate_slot");if(slot>=0&&slot<c.getContainerSize())c.getItems().set(slot,refs[integer(op,"replace_ref")]);}}
 }
 static final class C extends SimpleContainer {Data d;C(ItemStack[] slots){super(slots);}@Override public void setChanged(){d.event("changed");}@Override public int getMaxStackSize(){d.event("max");return integer(d.op,"max");}}
 @SuppressWarnings("unchecked")public static void main(String[] args)throws Exception {
  net.minecraft.SharedConstants.tryDetectVersion();net.minecraft.server.Bootstrap.bootStrap();items=new Item[]{Items.AIR,Items.STICK,Items.SHIELD};keys=new DataComponentType[]{DataComponents.MAX_STACK_SIZE,DataComponents.DAMAGE,DataComponentType.<Integer>builder().persistent(Codec.INT).build()};components=field(ItemStack.class,"components");count=field(ItemStack.class,"count");patchMap=field(DataComponentPatch.class,"map");removed=field(Class.forName("net.minecraft.core.component.Removed"),"INSTANCE").get(null);Path dir=Path.of(args[1]);
  try(var out=new PrintWriter(Files.newBufferedWriter(dir.resolve(args[0]+".txt")));var lines=Files.lines(dir.resolve("inputs.txt"))){for(var line:(Iterable<String>)lines::iterator){var f=JsonParser.parseString(line).getAsJsonObject();for(int i=0;i<3;i++)items[i].builtInRegistryHolder().bindComponents(prototype(f.getAsJsonArray("prototypes").get(i).getAsJsonArray()));ItemStack.EMPTY.setCount(0);ItemStack.EMPTY.setPopTime(0);((PatchedDataComponentMap)components.get(ItemStack.EMPTY)).clearPatch();var d=new Data();d.out=out;d.identities.put(ItemStack.EMPTY,0);d.refs=new ItemStack[f.getAsJsonArray("stacks").size()];for(int i=0;i<d.refs.length;i++){var v=f.getAsJsonArray("stacks").get(i).getAsJsonObject();int type=integer(v,"item");d.refs[i]=type<0?ItemStack.EMPTY:new ItemStack(items[type],integer(v,"count"));if(type>=0){d.refs[i].setPopTime(integer(v,"pop"));((PatchedDataComponentMap)components.get(d.refs[i])).restorePatch(patch(v.getAsJsonArray("patch")));}}var slots=new ItemStack[f.getAsJsonArray("slots").size()];for(int i=0;i<slots.length;i++)slots[i]=d.refs[f.getAsJsonArray("slots").get(i).getAsInt()];d.c=new C(slots);d.c.d=d;d.all();for(var ov:f.getAsJsonArray("ops")){var op=ov.getAsJsonObject();d.op=op;d.calls=0;int a=integer(op,"a"),b=integer(op,"b"),slot=integer(op,"slot"),amount=integer(op,"amount");try{switch(op.get("kind").getAsString()){
   case "set":d.c.setItem(slot,d.refs[a]);break;case "add":d.refs[b]=d.c.addItem(d.refs[a]);break;case "remove":d.refs[b]=d.c.removeItem(slot,amount);break;case "remove-type":d.refs[b]=d.c.removeItemType(items[integer(op,"item")],amount);break;case "no-update":d.refs[b]=d.c.removeItemNoUpdate(slot);break;case "clear":d.c.clearContent();break;case "all":var result=d.c.removeAllItems();out.println("all-size "+result.size());for(var s:result)out.println("removed "+d.snapshot(s));break;case "can-add":out.println("can-add "+d.c.canAddItem(d.refs[a]));break;case "get":d.refs[b]=d.c.getItem(slot);break;case "alias":d.refs[b]=d.refs[a];break;case "copy":d.refs[b]=d.refs[a].copy();break;case "count":d.refs[a].setCount(amount);break;case "component":d.refs[a].set(keys[integer(op,"key")],op.get("value").isJsonNull()?null:integer(op,"value"));break;default:throw new AssertionError();}out.println("result ok "+d.calls);}catch(Stop|IndexOutOfBoundsException|NullPointerException e){out.println("result error "+d.calls);}d.all();}}}
 }
}
